// Power factor and regulation
// 39: Power factor regulation (0-2000, offset +1000)
// 40: Active power regulation (0.1%)
// 41: Reactive power regulation (0.1%)

msg.baseAddr = 39;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 39,
    quantity: 3
};
return msg;

// Reconnection time
// 282: Restore connection time (10-300 seconds)

msg.baseAddr = 282;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 282,
    quantity: 1
};
return msg;

// Grid mode and voltage/frequency settings
// 284: Grid Mode
// 285: Grid Frequency (0=50Hz, 1=60Hz)
// 286: Grid Type
// 287: Grid Vol High (0.1V)
// 288: Grid Vol Low (0.1V)
// 289: Grid Hz High (0.01Hz)
// 290: Grid Hz Low (0.01Hz)

msg.baseAddr = 284;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 284,
    quantity: 7
};
return msg;

// Build GridCodeConfigState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("GridCodeConfigState: missing base address");
    return null;
}

// ---- Store partials ----

// Power regulation 39-41
if (baseAddr === 39) {
    const pfRaw = data[0] || 0;           // 39: offset +1000
    const activeReg = data[1] || 0;       // 40: 0.1%
    const reactiveReg = data[2] || 0;     // 41: 0.1%

    flow.set("gcc_part_power_reg", {
        powerFactorTarget: Math.round((pfRaw - 1000) * 100) / 100,  // -1.00 to +1.00
        activePowerRegulationPercentPerStep: Math.round(activeReg * 0.1 * 10) / 10,
        reactivePowerRegulationPercentPerStep: Math.round(reactiveReg * 0.1 * 10) / 10
    });
}

// Reconnection time 282
else if (baseAddr === 282) {
    flow.set("gcc_part_reconnect", {
        reconnectionTimeSeconds: data[0] || 0
    });
}

// Grid settings 284-290
else if (baseAddr === 284) {
    const gridMode = data[0] || 0;        // 284
    const gridFreq = data[1] || 0;        // 285: 0=50Hz, 1=60Hz
    const gridType = data[2] || 0;        // 286
    const volHigh = data[3] || 0;         // 287: 0.1V
    const volLow = data[4] || 0;          // 288: 0.1V
    const hzHigh = data[5] || 0;          // 289: 0.01Hz
    const hzLow = data[6] || 0;           // 290: 0.01Hz

    flow.set("gcc_part_grid_settings", {
        gridModeRaw: gridMode,
        gridFrequencyHz: gridFreq === 0 ? 50 : 60,
        gridVoltageLevelCode: gridType,
        voltageHighV: Math.round(volHigh * 0.1 * 10) / 10,
        voltageLowV: Math.round(volLow * 0.1 * 10) / 10,
        frequencyHighHz: Math.round(hzHigh * 0.01 * 100) / 100,
        frequencyLowHz: Math.round(hzLow * 0.01 * 100) / 100
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const powerRegPart = flow.get("gcc_part_power_reg");
const reconnectPart = flow.get("gcc_part_reconnect");
const gridSettingsPart = flow.get("gcc_part_grid_settings");

if (!powerRegPart || !reconnectPart || !gridSettingsPart) {
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

const state = {
    kind: "GridCodeConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,
    version: "1",

    gridModeRaw: gridSettingsPart.gridModeRaw,
    gridFrequencyHz: gridSettingsPart.gridFrequencyHz,
    gridVoltageLevelCode: gridSettingsPart.gridVoltageLevelCode,

    normalConnect: {
        voltageLowV: gridSettingsPart.voltageLowV,
        voltageHighV: gridSettingsPart.voltageHighV,
        frequencyLowHz: gridSettingsPart.frequencyLowHz,
        frequencyHighHz: gridSettingsPart.frequencyHighHz
    },

    reconnectionTimeSeconds: reconnectPart.reconnectionTimeSeconds,

    powerFactorTarget: powerRegPart.powerFactorTarget,
    activePowerRegulationPercentPerStep: powerRegPart.activePowerRegulationPercentPerStep,
    reactivePowerRegulationPercentPerStep: powerRegPart.reactivePowerRegulationPercentPerStep
};

// Clear partials
flow.set("gcc_part_power_reg", null);
flow.set("gcc_part_reconnect", null);
flow.set("gcc_part_grid_settings", null);

flow.set("gridCodeConfigSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;
